"""
JS per integrazione Outlook (usato dal route /outlook.js).
"""

_OUTLOOK_JS = "\n// -------- DROPDOWN OUTLOOK --------\nfunction toggleOutlookDropdown(evt, btn) {\n    evt.stopPropagation();\n    var wrap = btn.closest('.outlook-wrap');\n    var dd = wrap.querySelector('.outlook-dropdown');\n    var isOpen = dd.classList.contains('open');\n    document.querySelectorAll('.outlook-dropdown.open').forEach(function(d){ d.classList.remove('open'); });\n    if (!isOpen) dd.classList.add('open');\n}\ndocument.addEventListener('click', function() {\n    document.querySelectorAll('.outlook-dropdown.open').forEach(function(d){ d.classList.remove('open'); });\n});\ndocument.addEventListener('click', function(e) {\n    var dd = e.target.closest('.outlook-dropdown');\n    if (!dd) return;\n    var titolo = dd.dataset.titolo || '';\n    var data   = dd.dataset.data   || '';\n    var ora    = dd.dataset.ora    || '';\n    var url    = dd.dataset.url    || '';\n    if (e.target.classList.contains('dd-evento')) {\n        dd.classList.remove('open');\n        openOutlookEvento(titolo, data, ora, url);\n    }\n    if (e.target.classList.contains('dd-attivita')) {\n        dd.classList.remove('open');\n        openOutlookAttivita(titolo, data, ora, url);\n    }\n});\n\nfunction pad2(n) { return String(n).padStart(2, '0'); }\n\nfunction addHour(dateStr, timeStr) {\n    var dt = new Date(dateStr + 'T' + timeStr + ':00');\n    dt.setHours(dt.getHours() + 1);\n    var d = dt.getFullYear() + '-' + pad2(dt.getMonth()+1) + '-' + pad2(dt.getDate());\n    var t = pad2(dt.getHours()) + ':' + pad2(dt.getMinutes());\n    return { data: d, ora: t };\n}\n\nfunction openOutlookEvento(titolo, data, ora, url) {\n    var oraInizio = ora || '09:00';\n    var fine = addHour(data, oraInizio);\n    var desc = (window.OL_STRINGS ? window.OL_STRINGS.eventoDesc : 'Evento da TaskPlanner') + ': ' + titolo;\n    if (url) desc += '\\n' + url;\n    document.getElementById('oe_oggetto').value        = titolo;\n    document.getElementById('oe_descrizione').value    = desc;\n    document.getElementById('oe_data_inizio').value    = data;\n    document.getElementById('oe_ora_inizio').value     = oraInizio;\n    document.getElementById('oe_data_fine').value      = fine.data;\n    document.getElementById('oe_ora_fine').value       = fine.ora;\n    document.getElementById('oe_data_inizio_fd').value = data;\n    document.getElementById('oe_data_fine_fd').value   = data;\n    document.getElementById('oe_fullday').checked      = false;\n    toggleFullDay();\n    closeOutlookModals();\n    document.getElementById('modalOutlookEvento').classList.add('open');\n    document.body.style.overflow = 'hidden';\n}\n\nfunction toggleFullDay() {\n    var fd = document.getElementById('oe_fullday').checked;\n    document.getElementById('oe_time_row').style.display    = fd ? 'none' : '';\n    document.getElementById('oe_end_row').style.display     = fd ? 'none' : '';\n    document.getElementById('oe_fullday_row').style.display = fd ? '' : 'none';\n}\n\nfunction eseguiCreaEvento() {\n    var oggetto = document.getElementById('oe_oggetto').value.trim();\n    var desc    = document.getElementById('oe_descrizione').value.trim();\n    var fullday = document.getElementById('oe_fullday').checked;\n    var payload = { titolo: oggetto, descrizione: desc, fullday: fullday };\n\n    if (fullday) {\n        payload.data_inizio = document.getElementById('oe_data_inizio_fd').value;\n        payload.data_fine   = document.getElementById('oe_data_fine_fd').value;\n    } else {\n        payload.data_inizio = document.getElementById('oe_data_inizio').value;\n        payload.ora_inizio  = document.getElementById('oe_ora_inizio').value;\n        payload.data_fine   = document.getElementById('oe_data_fine').value;\n        payload.ora_fine    = document.getElementById('oe_ora_fine').value;\n    }\n\n    var btn = document.querySelector('#modalOutlookEvento .btn-outlook-confirm');\n    var _oe_orig_text = btn ? btn.textContent : '';\n    if (btn) { btn.disabled = true; btn.textContent = window.OL_STRINGS.creazione; }\n\n    fetch('/outlook/crea_evento', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(payload)\n    })\n    .then(function(r){ return r.json(); })\n    .then(function(res) {\n        if (res.ok) {\n            closeOutlookModals();\n            alert(window.OL_STRINGS.eventoCreato);\n        } else {\n            alert(window.OL_STRINGS.errore + ' ' + (res.error || window.OL_STRINGS.erroresSconosciuto));\n        }\n    })\n    .catch(function(e) {\n        alert(window.OL_STRINGS.erroreRete + ' ' + e);\n    })\n    .finally(function() {\n        if (btn) { btn.disabled = false; btn.textContent = _oe_orig_text || '📆'; }\n    });\n}\n\nfunction openOutlookAttivita(titolo, data, ora, url) {\n    var oraTask = ora || '09:00';\n    var desc = (window.OL_STRINGS ? window.OL_STRINGS.attivitaDesc : 'Attività da TaskPlanner') + ': ' + titolo;\n    if (url) desc += '\\n' + url;\n    document.getElementById('oa_oggetto').value     = titolo;\n    document.getElementById('oa_descrizione').value = desc;\n    document.getElementById('oa_data').value        = data;\n    document.getElementById('oa_ora').value         = oraTask;\n    closeOutlookModals();\n    document.getElementById('modalOutlookAttivita').classList.add('open');\n    document.body.style.overflow = 'hidden';\n}\n\nfunction eseguiCreaAttivita() {\n    var oggetto = document.getElementById('oa_oggetto').value.trim();\n    var desc    = document.getElementById('oa_descrizione').value.trim();\n    var data    = document.getElementById('oa_data').value;\n    var ora     = document.getElementById('oa_ora').value;\n\n    var btn = document.querySelector('#modalOutlookAttivita .btn-outlook-confirm');\n    var _oa_orig_text = btn ? btn.textContent : '';\n    if (btn) { btn.disabled = true; btn.textContent = window.OL_STRINGS.creazione; }\n\n    fetch('/outlook/crea_attivita', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ titolo: oggetto, data_scadenza: data, ora: ora, descrizione: desc })\n    })\n    .then(function(r){ return r.json(); })\n    .then(function(res) {\n        if (res.ok) {\n            closeOutlookModals();\n            alert(window.OL_STRINGS.attivitaCreata);\n        } else {\n            alert(window.OL_STRINGS.errore + ' ' + (res.error || window.OL_STRINGS.erroresSconosciuto));\n        }\n    })\n    .catch(function(e) {\n        alert(window.OL_STRINGS.erroreRete + ' ' + e);\n    })\n    .finally(function() {\n        if (btn) { btn.disabled = false; btn.textContent = _oa_orig_text || '☑️'; }\n    });\n}\n\nfunction closeOutlookModals() {\n    document.querySelectorAll('.modal-outlook-overlay').forEach(function(m){ m.classList.remove('open'); });\n    document.body.style.overflow = '';\n}\ndocument.addEventListener('DOMContentLoaded', function() {\n    document.querySelectorAll('.modal-outlook-overlay').forEach(function(m) {\n        m.addEventListener('click', function(e) {\n            if (e.target === m) closeOutlookModals();\n        });\n    });\n    document.addEventListener('keydown', function(e) {\n        if (e.key === 'Escape') closeOutlookModals();\n    });\n});\n"
